// 小学3年生・社会（学校の 学習範囲。中学受験の 土台）。
export const gradeE3ShakaiQuestions: Question[] = [
  {"id": "grade_e3_shakai_001", "subject": "shakai", "question": "ふつうの地図では、北は地図の上・下・右・左のどこにかかれていますか。「上」「下」「右」「左」のどれかで答えましょう。", "answer": "上", "hint": "地図を見るとき、ほういじしんの赤いはりが、地図のどちらをむくかを思い出そう。", "explanation": "【何を聞かれているか】地図で、北がかかれている向（む）き。\n\n【なぜこの答えか】ふつうの地図は、北が上になるようにかかれているから。北が上だと、右が東、左が西、下が南と、ほういを決（き）めやすい。\n\n【ステップ1】ふつうの地図は、北を上にしてかく\n【ステップ2】北が上のとき、右は東、左は西、下は南になる\n\n【答え】上\n\n【たしかめ】地図のすみにほういの矢じるしがあるときは、矢じるしの先が上をむいているかをたしかめる。\n\n【よくあるまちがい】下や右と答えてしまう。地図は北が上とおぼえる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_002", "subject": "shakai", "question": "北を上にした地図で、右がわにあたるほういはどれですか。漢字（かんじ）1字で答えましょう。", "answer": "東", "hint": "北をむいて立ったとき、右手はどちらのほういをさすか考えよう。", "explanation": "【何を聞かれているか】北が上の地図で、右にあたるほうい。\n\n【なぜこの答えか】北をむいて立つと、右手がわが東、左手がわが西、うしろが南になる。地図でも同じ向（む）きに、右が東、左が西になるから。\n\n【ステップ1】まず北を上にする\n【ステップ2】北をむいて立ったときの右手がわを考える\n【ステップ3】右手がわのほういは東\n\n【答え】東\n\n【たしかめ】東は日が出てくるほう。朝、日が出るほうがわが右がわになっているか思いうかべる。\n\n【よくあるまちがい】右を西と答えてしまう。北が上なら、右は東とおぼえる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_003", "subject": "shakai", "question": "東の反対（はんたい）のほういはどれですか。漢字（かんじ）1字で答えましょう。", "answer": "西", "hint": "日がしずむほうだよ。", "explanation": "【何を聞かれているか】東とは反対（はんたい）がわにあたるほうい。\n\n【なぜこの答えか】東と西は、まっすぐむかい合ったほういだから。東から日が出て、反対がわの西にしずむ。\n\n【ステップ1】東の反対がわをさがす\n【ステップ2】地図で東が右なら、左がわが反対\n【ステップ3】左がわのほういは西\n\n【答え】西\n\n【たしかめ】北が上の地図で、右が東、左が西になっていることをたしかめる。\n\n【よくあるまちがい】東と西を入れかえてしまう。右が東、左が西。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_004", "subject": "shakai", "question": "地図で、北と東のちょうど間にあたるほういを、漢字（かんじ）2字で何といいますか。", "answer": "北東", "hint": "北と東の、ちょうどまん中にあたるほういだよ。", "explanation": "【何を聞かれているか】北と東の間にあたるほういの名前。\n\n【なぜこの答えか】北と東のちょうど間にあたるほういだから。ほういを四つよりこまかく言うとき、間のほういは二つの名前をならべて言い、このほういは北東となる。\n\n【ステップ1】北は上、東は右\n【ステップ2】上と右の間のななめの向（む）きを考える\n【ステップ3】北と東の間のほういを「北東」と言う\n\n【答え】北東\n\n【たしかめ】地図で、上の方向と右の方向の間に北東があることをたしかめる。\n\n【よくあるまちがい】「東北」とぎゃくに書く。ここでは北を先に言う。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_005", "subject": "shakai", "question": "北・北東・東・南東・南・南西・西・北西のように、ほういをこまかく分けると、ほういはぜんぶでいくつになりますか。数字で答えましょう。", "answer": "8", "hint": "名前を一つずつ数えていこう。北からぐるっと一まわりするよ。", "explanation": "【何を聞かれているか】ほういをこまかく分けたときの数。\n\n【なぜこの答えか】東西南北の四つに、その間の北東・南東・南西・北西の四つをくわえるので、ぜんぶで八つになるから。\n\n【ステップ1】東西南北は4つ\n【ステップ2】間のほういは北東・南東・南西・北西の4つ\n【ステップ3】4＋4＝8\n\n【答え】8\n\n【たしかめ】北から時計まわりに、北・北東・東・南東・南・南西・西・北西と声に出して数え、8つになるかたしかめる。\n\n【よくあるまちがい】東西南北の4だけで答えてしまう。間のほういもわすれずに数える。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_006", "subject": "shakai", "question": "ほういじしんの赤いはりは、どのほういをさしますか。", "answer": "北", "hint": "ふつうの地図で、いちばん上にあたるほういと同じだよ。", "explanation": "【何を聞かれているか】ほういじしんの赤いはりがさすほうい。\n\n【なぜこの答えか】ほういじしんの赤いはりは、いつも北をさすようにできているから。はりが止まったら、赤いはりのさきが北なので、そこから東・西・南がわかる。\n\n【ステップ1】ほういじしんを、水平（すいへい）な所（ところ）におく\n【ステップ2】はりが止まるのを待（ま）つ\n【ステップ3】赤いはりのさきが北\n\n【答え】北\n\n【たしかめ】赤いはりが北をさしたとき、反対（はんたい）の白いはりは南をさしているかたしかめる。\n\n【よくあるまちがい】南をさすと思ってしまう。赤いはりは北。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["北", "南", "東"]},
  {"id": "grade_e3_shakai_007", "subject": "shakai", "question": "地図記号（ごう）「〒」は、何をあらわしていますか。", "answer": "ゆうびん局", "hint": "手紙やはがきを出したり、とどけたりするところだよ。", "explanation": "【何を聞かれているか】地図記号（ごう）「〒」の意味（いみ）。\n\n【なぜこの答えか】「〒」は、ゆうびん局（きょく）をあらわす地図記号で、手紙をあつかうところに使（つか）われるから。地図記号は、ひと目でその場所（ばしょ）がわかるようにきめられている。\n\n【ステップ1】地図のはんれいで「〒」をさがす\n【ステップ2】「〒」はゆうびん局の記号\n\n【答え】ゆうびん局\n\n【たしかめ】地図のはんれいを見て、「〒」の横（よこ）にゆうびん局と書いてあるかたしかめる。\n\n【よくあるまちがい】市役所（しやくしょ）や交番とまちがえる。それぞれちがう記号をもつ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["市役所", "ゆうびん局", "交番"]},
  {"id": "grade_e3_shakai_008", "subject": "shakai", "question": "地図記号（ごう）「文」は、何をあらわしていますか。", "answer": "学校", "hint": "毎日、みんなが勉強（べんきょう）しに行く場所（ばしょ）だよ。", "explanation": "【何を聞かれているか】地図記号（ごう）「文」の意味（いみ）。\n\n【なぜこの答えか】「文」は、学校をあらわす地図記号で、どの地図でも学校のところに使（つか）われるから。地図記号は、ひと目で場所（ばしょ）がわかるように決（き）められている。\n\n【ステップ1】地図のはんれいで「文」をさがす\n【ステップ2】「文」は学校をあらわす記号\n\n【答え】学校\n\n【たしかめ】自分の通う学校のある場所に「文」がかかれているか、町の地図でたしかめる。\n\n【よくあるまちがい】病院（びょういん）や市役所（しやくしょ）の記号と見まちがえる。「文」は学校。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["病院", "市役所", "学校"]},
  {"id": "grade_e3_shakai_009", "subject": "shakai", "question": "次（つぎ）のうち、米や野さいなどの作物（さくもつ）をつくる土地ではないものはどれですか。", "answer": "工場", "hint": "作物（さくもつ）をそだてるのではなく、品物（しなもの）をつくるところだよ。", "explanation": "【何を聞かれているか】作物（さくもつ）をつくる土地ではないものをえらぶ。\n\n【なぜこの答えか】田と畑（はたけ）は、米や野さいなどの作物をそだてる土地。工場は、きかいなどを使（つか）って品物（しなもの）をつくるところで、作物をそだてる土地ではないから。\n\n【ステップ1】田は米をそだてる土地\n【ステップ2】畑は野さいなどをそだてる土地\n【ステップ3】工場は品物をつくるところなので、作物の土地ではない\n\n【答え】工場\n\n【たしかめ】土地の使われ方は、地図記号（ごう）や色分けで見分けられる。田・畑は作物、工場は品物ときりはなして考える。\n\n【よくあるまちがい】工場も土地の使われ方のひとつなので、ちがいをおぼえずにまちがえる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["工場", "田", "畑"]},
  {"id": "grade_e3_shakai_010", "subject": "shakai", "question": "市の地図で、山・川・海のうち、山から海へ向（む）かって流（なが）れる、水の通り道はどれですか。漢字（かんじ）1字で答えましょう。", "answer": "川", "hint": "水が高い所（ところ）からひくい所へ流（なが）れて、細長くのびている所だよ。", "explanation": "【何を聞かれているか】山から海へ水を運（はこ）ぶ、細長い水の道。\n\n【なぜこの答えか】雨や雪どけの水は、高い所（ところ）からひくい所へ流（なが）れて集（あつ）まり、川になって海へ出ていくから。\n\n【ステップ1】山は高い土地、海は水がたまった広い所\n【ステップ2】山から海へ細長くつづく水の流れを考える\n【ステップ3】水の流れる細長い道は川\n\n【答え】川\n\n【たしかめ】地図で川の線をたどり、山の近くから海のほうへつながっているかたしかめる。\n\n【よくあるまちがい】海や池と答えてしまう。山から海へつながる細長い流れは川。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_011", "subject": "shakai", "question": "市の人びとのくらしにかかわるさまざまな手つづき（ひっこしのとどけなど）をするたてものはどれですか。", "answer": "市役所", "hint": "市の仕事（しごと）をする人たちがはたらいているたてものだよ。", "explanation": "【何を聞かれているか】市のさまざまな手つづきをするたてもの。\n\n【なぜこの答えか】市役所（しやくしょ）は、市の人たちのくらしにひつような手つづきや、市の仕事（しごと）を行うところだから。ひっこしや、戸せきのとどけなどもここで行う。\n\n【ステップ1】市のくらしにかかわる手つづきを考える\n【ステップ2】図書館（としょかん）や駅（えき）は、手つづきの場所ではない\n【ステップ3】手つづきをするたてものは市役所\n\n【答え】市役所\n\n【たしかめ】地図で◎の記号（ごう）を見つけ、市役所の場所をたしかめる。\n\n【よくあるまちがい】図書館や駅とまちがえる。手つづきをするのは市役所。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["図書館", "駅", "市役所"]},
  {"id": "grade_e3_shakai_012", "subject": "shakai", "question": "本をかりたり、その場で読んだりできる、こうきょうのたてものはどれですか。", "answer": "図書館", "hint": "図書という字が名前に入っているよ。", "explanation": "【何を聞かれているか】本をかりたり読んだりできるたてもの。\n\n【なぜこの答えか】図書館（としょかん）は、たくさんの本を集（あつ）めて、みんなが読んだりかりたりできるようにしたたてものだから。\n\n【ステップ1】本があるたてものを考える\n【ステップ2】駅（えき）や市役所（しやくしょ）は、本をかりる場所ではない\n【ステップ3】本をかりられるのは図書館\n\n【答え】図書館\n\n【たしかめ】図書館のカードがあれば、かりられる本があることを思い出してたしかめる。\n\n【よくあるまちがい】市役所と答えてしまう。本をかりるのは図書館。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["図書館", "駅", "市役所"]},
  {"id": "grade_e3_shakai_013", "subject": "shakai", "question": "電車のように、レールの上を走る乗（の）り物（もの）の通り道を、何といいますか。漢字（かんじ）2字で答えましょう。", "answer": "鉄道", "hint": "電車の通り道だよ。", "explanation": "【何を聞かれているか】電車が走る通り道の名前。\n\n【なぜこの答えか】電車は、レールの上を走る乗（の）り物（もの）で、そのレールがしかれた通り道を鉄道（てつどう）と言うから。道路（どうろ）は、車やバスが走る道。\n\n【ステップ1】電車はレールの上を走る\n【ステップ2】レールの通り道を考える\n【ステップ3】レールの通り道は鉄道\n\n【答え】鉄道\n\n【たしかめ】地図で、電車の線と道路の線が、ちがう線になっていることをたしかめる。\n\n【よくあるまちがい】道路と答えてしまう。レールがあるのが鉄道、車が走るのが道路。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_014", "subject": "shakai", "question": "市の地図を作るとき、山や川の形だけがかいてあって、何も書きこまれていない地図を何といいますか。漢字（かんじ）3字で答えましょう。", "answer": "白地図", "hint": "色がついていない、まっ白な地図だよ。", "explanation": "【何を聞かれているか】何も書きこんでいない地図の名前。\n\n【なぜこの答えか】白地図は、形だけがかいてあるので、自分で調（しら）べたことを自由（じゆう）に書きこめるから。調べたことをまとめるときに使（つか）う。\n\n【ステップ1】何も書きこまれていない地図を考える\n【ステップ2】白い紙のような地図\n【ステップ3】白地図と言う\n\n【答え】白地図\n\n【たしかめ】白地図に、学校や駅（えき）のいちを色分けして書き入れてみると、自分の町の地図ができる。\n\n【よくあるまちがい】絵地図とまちがえる。絵地図は絵をかきこんだ地図。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_015", "subject": "shakai", "question": "地図の中の記号（ごう）の意味（いみ）を書いた表（ひょう）を、何と言いますか。ひらがな4字で答えましょう。", "answer": "はんれい", "hint": "地図のすみに書いてある、記号（ごう）と意味（いみ）が組になった表（ひょう）だよ。", "explanation": "【何を聞かれているか】地図の記号（ごう）の意味（いみ）を書いた表（ひょう）の名前。\n\n【なぜこの答えか】地図には、記号がたくさん出てくるので、それぞれの意味がわかるように、まとめて書いた表がいる。それが「はんれい」だから。\n\n【ステップ1】地図のすみの小さな表を見る\n【ステップ2】記号と意味が組になっている\n【ステップ3】この表をはんれいと言う\n\n【答え】はんれい\n\n【たしかめ】地図の記号の意味をはんれいで読んで、地図の中の記号と同じ形かたしかめる。\n\n【よくあるまちがい】ほういの矢じるしをはんれいと思ってしまう。矢じるしは向（む）きをしめす。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_016", "subject": "shakai", "question": "川の水は、山からどこに向（む）かって流（なが）れていきますか。", "answer": "海", "hint": "川の水は、さいごに大きな水たまりに入るよ。", "explanation": "【何を聞かれているか】川の水が流（なが）れていく先。\n\n【なぜこの答えか】川の水は、高い所（ところ）からひくい所へ向（む）かって流れ、たくさんの水が集（あつ）まって、さいごに海に入るから。\n\n【ステップ1】川は山から流れ出す\n【ステップ2】水は高い所からひくい所へ流れる\n【ステップ3】ひくい所のいちばん先は海\n\n【答え】海\n\n【たしかめ】市の地図で、川のおわりが海につながっているか、たしかめる。\n\n【よくあるまちがい】山へ向かって流れると思ってしまう。水はひくいほうへ流れる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["山", "海", "田"]},
  {"id": "grade_e3_shakai_017", "subject": "shakai", "question": "ある市の地図には、市役所（しやくしょ）の記号（ごう）が1つ、図書館（としょかん）の記号が2つ、学校の記号が5つあります（たとえばの話です）。図書館と学校の記号を合わせると、いくつありますか。数字で答えましょう。", "answer": "7", "hint": "市役所（しやくしょ）は数えないよ。図書館（としょかん）と学校だけをたそう。", "explanation": "【何を聞かれているか】図書館（としょかん）と学校の記号（ごう）をたした数。\n\n【なぜこの答えか】聞かれているのは図書館と学校だけだから。市役所（しやくしょ）の1つは数えずに、図書館の2つと学校の5つをたせばよい。\n\n【ステップ1】図書館は2つ\n【ステップ2】学校は5つ\n【ステップ3】2＋5＝7\n\n【答え】7\n\n【たしかめ】5から数えて、2つ分すすむと7になることをたしかめる。\n\n【よくあるまちがい】市役所の1つも入れて8と答えてしまう。聞かれたものだけを数える。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_018", "subject": "shakai", "question": "米づくりで、春のはじめに、いちばん先にする仕事（しごと）はどれですか。", "answer": "田おこし", "hint": "田の土をほりかえして、やわらかくする仕事（しごと）だよ。", "explanation": "【何を聞かれているか】米づくりで、いちばん先にする仕事（しごと）。\n\n【なぜこの答えか】米づくりは、まず田の土をほりおこして、やわらかくする田おこしからはじまるから。そのあとにしろかき、田うえとすすむ。\n\n【ステップ1】米づくりの仕事のじゅんを思い出す\n【ステップ2】田おこし→しろかき→田うえ→水のせわ→いねかり\n【ステップ3】いちばん先は田おこし\n\n【答え】田おこし\n\n【たしかめ】田おこしをしないと、土がかたいので、いねの根（ね）がのびにくいことを思い出してたしかめる。\n\n【よくあるまちがい】田うえを先にしてしまう。田おこしが先。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["田おこし", "田うえ", "いねかり"]},
  {"id": "grade_e3_shakai_019", "subject": "shakai", "question": "田うえの前に、田に水を入れて、土をていねいにならす仕事（しごと）を何といいますか。ひらがな4字で答えましょう。", "answer": "しろかき", "hint": "田おこしの次（つぎ）にする仕事（しごと）で、田の土を平（たい）らにするんだよ。", "explanation": "【何を聞かれているか】田うえの前に、水を入れて土をならす仕事（しごと）。\n\n【なぜこの答えか】田に水を入れて土をこまかくかきまぜ、平（たい）らにならすと、いねをまっすぐ植（う）えやすく、水もむらなくたまるから。この仕事を「しろかき」と言う。\n\n【ステップ1】田おこしの次（つぎ）の仕事を考える\n【ステップ2】水を入れて土を平らにならす\n【ステップ3】この仕事をしろかきと言う\n\n【答え】しろかき\n\n【たしかめ】田おこし→しろかき→田うえのじゅんに、じゅんばんに言ってみる。\n\n【よくあるまちがい】田おこしとまちがえる。田おこしは土をほりおこす仕事、しろかきは水を入れてならす仕事。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_020", "subject": "shakai", "question": "米づくりの一年で、秋にいねの実（みの）ったほをかりとる仕事（しごと）を何といいますか。ひらがな4字で答えましょう。", "answer": "いねかり", "hint": "黄色くなったいねを、かまなどでかりとるよ。", "explanation": "【何を聞かれているか】秋に行う、いねをかりとる仕事（しごと）。\n\n【なぜこの答えか】秋になると、いねのほがみのって黄色くなる。そのときにかりとるので、この仕事を「いねかり」と言うから。\n\n【ステップ1】いねがそだつと、秋にはみのる\n【ステップ2】黄色くなったほをかりとる\n【ステップ3】この仕事をいねかりと言う\n\n【答え】いねかり\n\n【たしかめ】米づくりの一年を、春・夏・秋のじゅんに、仕事の名前をならべて言ってみる。\n\n【よくあるまちがい】田うえとまちがえる。田うえは春、いねかりは秋。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_021", "subject": "shakai", "question": "米づくりの仕事（しごと）を、田おこし→しろかき→田うえ→水のせわ→いねかり、のじゅんにならべると、田うえは何番目ですか。数字で答えましょう。", "answer": "3", "hint": "一つずつ、じゅん番に数えていこう。", "explanation": "【何を聞かれているか】田うえが何番目の仕事（しごと）か。\n\n【なぜこの答えか】田おこしが1番目、しろかきが2番目、その次（つぎ）の田うえが3番目になるから。じゅん番をまちがえると、田に水がないのになえを植（う）えることになってしまう。\n\n【ステップ1】田おこしは1番目\n【ステップ2】しろかきは2番目\n【ステップ3】その次の田うえは3番目\n\n【答え】3\n\n【たしかめ】5つの仕事を、指（ゆび）をおりながら、じゅんに数えて、3番目が田うえかたしかめる。\n\n【よくあるまちがい】水のせわと入れかえて4番目と答えてしまう。水のせわは田うえのあと。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_022", "subject": "shakai", "question": "田うえのあと、いねがそだつ夏のあいだに、農家（のうか）の人が田で行う仕事（しごと）はどれですか。", "answer": "水のせわ", "hint": "いねは水がないとかれてしまうよ。", "explanation": "【何を聞かれているか】夏に田で行う仕事（しごと）。\n\n【なぜこの答えか】夏は、いねがぐんぐんそだつときで、田の水が多すぎたり少なすぎたりするとよくそだたない。だから、水のりょうを見て、水のせわをするから。\n\n【ステップ1】夏はいねがそだつ時期（じき）\n【ステップ2】いねには水が大切\n【ステップ3】水を見まわる仕事をする\n\n【答え】水のせわ\n\n【たしかめ】田おこし・田うえは春、いねかりは秋と分けて、夏が水のせわだとたしかめる。\n\n【よくあるまちがい】田うえやいねかりと答えてしまう。夏はそだてる世話（せわ）をする時期。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["田おこし", "水のせわ", "いねかり"]},
  {"id": "grade_e3_shakai_023", "subject": "shakai", "question": "ビニールでおおったたてものの中で、野さいをそだてるしせつを、カタカナ3字で何といいますか。", "answer": "ハウス", "hint": "寒（さむ）いきせつでも、中があたたかいよ。", "explanation": "【何を聞かれているか】野さいをそだてる、ビニールでおおったたてもの。\n\n【なぜこの答えか】ビニールでおおうと、中があたたかくなり、風や雨からも作物（さくもつ）を守（まも）れるから。寒（さむ）い時期（じき）でも野さいをそだてられる。\n\n【ステップ1】野さいをそだてるたてものを考える\n【ステップ2】ビニールで中をあたためる\n【ステップ3】このしせつをハウスと言う\n\n【答え】ハウス\n\n【たしかめ】ハウスの中は外よりあたたかいことを思い出して、そだてやすいかたしかめる。\n\n【よくあるまちがい】田や畑（はたけ）と同じだと思ってしまう。ハウスは、たてものの中でそだてるしせつ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_024", "subject": "shakai", "question": "キャベツやだいこんなどの野さいを主（おも）にそだてる土地は、田と畑（はたけ）のどちらですか。漢字（かんじ）1字で答えましょう。", "answer": "畑", "hint": "田は水をためて、米をそだてるところだよ。", "explanation": "【何を聞かれているか】野さいをそだてる土地の名前。\n\n【なぜこの答えか】田は水をためて米をそだてる土地。キャベツやだいこんのような野さいは、水をためずに、土の上でそだてるので畑（はたけ）を使（つか）うから。\n\n【ステップ1】田は水をためて米をつくる\n【ステップ2】野さいは水をためずに土でそだてる\n【ステップ3】野さいの土地は畑\n\n【答え】畑\n\n【たしかめ】地図記号（ごう）で、田と畑がちがう形になっていることもたしかめられる。\n\n【よくあるまちがい】田と答えてしまう。米は田、野さいは畑。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_025", "subject": "shakai", "question": "農家（のうか）の人が、作物（さくもつ）がよくそだつように、田や畑（はたけ）の土にくわえる、えいようになるものを何といいますか。ひらがな4字で答えましょう。", "answer": "ひりょう", "hint": "土を元気にして、作物（さくもつ）がよくそだつようにするものだよ。", "explanation": "【何を聞かれているか】土にくわえる、作物（さくもつ）のえいようになるもの。\n\n【なぜこの答えか】同じ土地で作物をそだてつづけると、土のえいようが少なくなる。そこで、えいようをおぎなうために、ひりょうを入れるから。\n\n【ステップ1】作物は土のえいようをすう\n【ステップ2】えいようが足りなくなる\n【ステップ3】えいようをおぎなうものをひりょうと言う\n\n【答え】ひりょう\n\n【たしかめ】ひりょうを入れた畑（はたけ）と入れない畑で、作物のそだち方がちがうことを思いうかべる。\n\n【よくあるまちがい】水と答えてしまう。水はひりょうではない。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_026", "subject": "shakai", "question": "田うえをするのは、春・夏・秋・冬のどのきせつですか。漢字（かんじ）1字で答えましょう。", "answer": "春", "hint": "田おこし、しろかきのあとにするよ。", "explanation": "【何を聞かれているか】田うえをするきせつ。\n\n【なぜこの答えか】米づくりは、春に田おこし、しろかき、田うえをして、夏に水のせわ、秋にいねかりをする流（なが）れだから。\n\n【ステップ1】田おこしは春のはじめ\n【ステップ2】しろかきのあとに田うえ\n【ステップ3】田うえも春\n\n【答え】春\n\n【たしかめ】春・夏・秋の仕事（しごと）を、じゅんに言ってみて、田うえが春に入っているかたしかめる。\n\n【よくあるまちがい】夏と答えてしまう。夏は水のせわ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_027", "subject": "shakai", "question": "工場でできあがった品物（しなもの）を、店などにはこび出すことを、漢字（かんじ）2字で何といいますか。", "answer": "出荷", "hint": "「出」す、「荷（に）」物（もの）を、という字を使（つか）うよ。", "explanation": "【何を聞かれているか】工場から品物（しなもの）をはこび出すこと。\n\n【なぜこの答えか】工場でできあがった品物は、工場の中においておくだけでは売れない。店などへ送（おく）り出すことを出荷（しゅっか）と言うから。\n\n【ステップ1】工場で品物ができあがる\n【ステップ2】店などへ送り出す\n【ステップ3】この仕事（しごと）を出荷と言う\n\n【答え】出荷\n\n【たしかめ】出荷のあと、品物が店にならぶという流（なが）れで、つながるかたしかめる。\n\n【よくあるまちがい】運（はこ）びこみと答えてしまう。運びこみは、ざいりょうを工場に入れること。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_028", "subject": "shakai", "question": "工場で、品物（しなもの）をつくるもとになるものを、ひらがな5字で何といいますか。", "answer": "ざいりょう", "hint": "車なら鉄（てつ）、パンならこむぎこのようなものだよ。", "explanation": "【何を聞かれているか】品物（しなもの）をつくるもとになるもの。\n\n【なぜこの答えか】品物をつくるには、もとになるものがいる。そのもとになるものをざいりょうと言うから。たとえば、パンならこむぎこがざいりょうになる。\n\n【ステップ1】品物には、もとになるものがある\n【ステップ2】パンの場合はこむぎこ\n【ステップ3】もとになるものをざいりょうと言う\n\n【答え】ざいりょう\n\n【たしかめ】ざいりょうが工場に運（はこ）びこまれてから、品物ができるというじゅんにたしかめる。\n\n【よくあるまちがい】せい品と答えてしまう。せい品は、できあがった品物のこと。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_029", "subject": "shakai", "question": "工場で、できあがった品物（しなもの）がまちがっていないか、よごれていないかをしらべる仕事（しごと）はどれですか。", "answer": "けんさ", "hint": "できあがった品物（しなもの）を出す前にする仕事（しごと）だよ。", "explanation": "【何を聞かれているか】品物（しなもの）をしらべる仕事（しごと）の名前。\n\n【なぜこの答えか】まちがった品物や、よごれた品物をお客（きゃく）さんにとどけてはいけないから。出荷（しゅっか）の前にしらべる仕事、けんさが大切になる。\n\n【ステップ1】できあがった品物がある\n【ステップ2】出荷の前にしらべる\n【ステップ3】このしらべる仕事がけんさ\n\n【答え】けんさ\n\n【たしかめ】工場の仕事の流（なが）れで、けんさが出荷の前に入っているかたしかめる。\n\n【よくあるまちがい】そうじと思ってしまう。そうじは、きれいにする仕事。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["ねだんづけ", "そうじ", "けんさ"]},
  {"id": "grade_e3_shakai_030", "subject": "shakai", "question": "食べ物（もの）をつくる工場で、はたらく人が白い服（ふく）やぼうしをつけて、手をよくあらうのは、食べ物をいつもどうしておくためですか。ひらがな4字で答えましょう。", "answer": "せいけつ", "hint": "よごれやごみが入らないようにするための気づかいだよ。", "explanation": "【何を聞かれているか】食べ物（もの）を、よごれのないようにしておく、というような意味（いみ）の言葉（ことば）。\n\n【なぜこの答えか】食べ物にごみや毛が入ったり、よごれがついたりすると、食べた人の体にわるいから。いつもよごれていない、せいけつなじょうたいにするためだから。\n\n【ステップ1】食べ物は口に入る\n【ステップ2】よごれがあると体にわるい\n【ステップ3】よごれていないじょうたいがせいけつ\n\n【答え】せいけつ\n\n【たしかめ】食べ物の工場の人が、白い服（ふく）や手あらいをしている理由（りゆう）を、せいけつという言葉でいえるかたしかめる。\n\n【よくあるまちがい】「きれい」と答えてしまう。ここでは、よごれていないことをあらわす「せいけつ」。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_031", "subject": "shakai", "question": "工場の仕事（しごと）のじゅんは、①ざいりょうの運（はこ）びこみ、②品物（しなもの）をつくる、③けんさ、④出荷（しゅっか）です。「品物をつくる」は何番目ですか。数字で答えましょう。", "answer": "2", "hint": "ざいりょうがないと、品物（しなもの）はつくれないよ。", "explanation": "【何を聞かれているか】「品物（しなもの）をつくる」が何番目か。\n\n【なぜこの答えか】ざいりょうがないと品物をつくれないので、先にざいりょうの運（はこ）びこみが来る。品物をつくったあとにけんさをして、さいごに出荷（しゅっか）する流（なが）れだから。\n\n【ステップ1】ざいりょうの運びこみが1番目\n【ステップ2】品物をつくるのが2番目\n【ステップ3】けんさは3番目、出荷は4番目\n\n【答え】2\n\n【たしかめ】1・2・3・4と数えて、2番目が品物をつくるになっているかたしかめる。\n\n【よくあるまちがい】運びこみの前に、つくると考えてしまう。ざいりょうがないと、つくれない。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_032", "subject": "shakai", "question": "工場でつくった品物（しなもの）を、店などへ運（はこ）ぶとき、道路（どうろ）を走る大きな車を、カタカナ4字で何といいますか。", "answer": "トラック", "hint": "荷物（にもつ）をたくさんつめる、大きな車だよ。", "explanation": "【何を聞かれているか】品物（しなもの）を運（はこ）ぶ大きな車の名前。\n\n【なぜこの答えか】トラックは荷物（にもつ）をたくさんつめる大きな車で、工場から店へ品物を運ぶときによく使（つか）われるから。\n\n【ステップ1】品物をたくさん運ぶ車を考える\n【ステップ2】荷台がある大きな車を思いうかべる\n【ステップ3】トラックと言う\n\n【答え】トラック\n\n【たしかめ】工場から店までの道を、トラックが走っているようすを思いうかべてたしかめる。\n\n【よくあるまちがい】バスと答えてしまう。バスは人を運ぶ車。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_033", "subject": "shakai", "question": "次（つぎ）のうち、工場でつくられるものはどれですか。", "answer": "自動車", "hint": "部品（ぶひん）を組み立てて、人が乗（の）る乗り物（もの）をつくるよ。", "explanation": "【何を聞かれているか】工場でつくられるもの。\n\n【なぜこの答えか】自動車（じどうしゃ）は、たくさんの部品（ぶひん）を集（あつ）めて、工場で組み立ててつくるから。いねやキャベツは、農家（のうか）の人が田や畑（はたけ）でそだてる。\n\n【ステップ1】工場は、ざいりょうから品物（しなもの）をつくる\n【ステップ2】いねとキャベツは、田や畑でそだてる\n【ステップ3】自動車は工場で組み立てる\n\n【答え】自動車\n\n【たしかめ】工場でつくるものか、田や畑でそだてるものかを分けて考えてたしかめる。\n\n【よくあるまちがい】農家のそだてるものも工場でつくると思ってしまう。そだてるものと、つくるものを分ける。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["自動車", "いね", "キャベツ"]},
  {"id": "grade_e3_shakai_034", "subject": "shakai", "question": "ある工場では、1日に120この品物（しなもの）をつくります（たとえばの話です）。5日間では何こつくりますか。数字で答えましょう。", "answer": "600", "hint": "1日分の数を、5回たすと同じことだよ。", "explanation": "【何を聞かれているか】5日間につくる品物（しなもの）の数。\n\n【なぜこの答えか】1日に120こつくるので、5日間なら120を5回たせばよいから。かけ算でも同じ答えになる。\n\n【ステップ1】1日分は120こ\n【ステップ2】5日間なので、120×5を計算する\n【ステップ3】120×5＝600\n\n【答え】600\n\n【たしかめ】120を5回たして、120＋120＋120＋120＋120＝600になることをたしかめる。\n\n【よくあるまちがい】1日分の数をそのまま答えてしまう。5日分をたすことをわすれない。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_035", "subject": "shakai", "question": "同じ形の部品（ぶひん）を、まちがいなく、はやく、たくさんつくるのがとくいなのは、きかいと人のどちらですか。ひらがな3字で答えましょう。", "answer": "きかい", "hint": "同じ動（うご）きをくりかえすのがとくいなほうだよ。", "explanation": "【何を聞かれているか】同じ部品（ぶひん）をたくさんつくるのがとくいなほう。\n\n【なぜこの答えか】きかいは同じ動（うご）きをいつも同じようにくりかえせるので、同じ形の部品をたくさんつくるのに向（む）いているから。人は細かい仕上（しあ）げやけんさに向いている。\n\n【ステップ1】同じ動きのくりかえしを考える\n【ステップ2】きかいは同じ動きをくりかえすのがとくい\n【ステップ3】答えはきかい\n\n【答え】きかい\n\n【たしかめ】工場の仕事（しごと）で、きかいと人が、それぞれ何をしているか、わけてたしかめる。\n\n【よくあるまちがい】人と答えてしまう。人は、細かい仕上げやけんさをうけもつことが多い。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_036", "subject": "shakai", "question": "店で、品物（しなもの）のねだんを書いて、品物につけたり、たなにかざったりする紙を何といいますか。ひらがな3字で答えましょう。", "answer": "ねふだ", "hint": "店で、品物（しなもの）のそばにおいてあるよ。", "explanation": "【何を聞かれているか】品物（しなもの）のねだんを書いた紙の名前。\n\n【なぜこの答えか】お客（きゃく）さんが買うかどうかを決（き）めるには、ねだんがわかることが大切。ねだんを書いた紙を品物につけるので、「ねふだ」と言うから。\n\n【ステップ1】お客さんは、ねだんを見て買う\n【ステップ2】ねだんを書いた紙をつける\n【ステップ3】その紙をねふだと言う\n\n【答え】ねふだ\n\n【たしかめ】店に行ったとき、品物のそばにねふだがあることを思い出してたしかめる。\n\n【よくあるまちがい】ポップと答えてしまう。ポップは、おすすめをしらせるカード。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_037", "subject": "shakai", "question": "新聞にはさんで、店の安（やす）い品物（しなもの）のしらせなどを配（くば）る紙を、カタカナ3字で何といいますか。", "answer": "チラシ", "hint": "朝、新聞といっしょに家にとどくことがあるよ。", "explanation": "【何を聞かれているか】店の品物（しなもの）をしらせる紙の名前。\n\n【なぜこの答えか】店は、安（やす）い品物やおとくな日を、お客（きゃく）さんにしらせたい。そこで、チラシにして、新聞にはさんだり、家に配（くば）ったりするから。\n\n【ステップ1】店がお客さんにしらせたいことを考える\n【ステップ2】安い品物のしらせを紙にして配る\n【ステップ3】この紙がチラシ\n\n【答え】チラシ\n\n【たしかめ】家にとどいたチラシを見て、店の名前や安い品物が書いてあるかたしかめる。\n\n【よくあるまちがい】新聞そのものと思ってしまう。チラシは新聞とはちがう紙。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_038", "subject": "shakai", "question": "スーパーマーケットで、肉・魚・野さいをしゅるいごとにならべるのは、だれが買いやすいようにするためですか。", "answer": "お客さん", "hint": "店に来て、品物（しなもの）をえらんで買う人たちのことだよ。", "explanation": "【何を聞かれているか】しゅるいごとにならべる、店のくふうのもくてき。\n\n【なぜこの答えか】品物（しなもの）がしゅるいごとにならんでいると、お客（きゃく）さんが、ほしいものをすぐに見つけられて、買いやすいから。店は、お客さんが買いやすいようにくふうしている。\n\n【ステップ1】店の人は、品物をならべる\n【ステップ2】買う人は、ほしいものを見つけたい\n【ステップ3】しゅるいごとだと、お客さんが買いやすい\n\n【答え】お客さん\n\n【たしかめ】スーパーの中で、肉や魚、野さいのコーナーが分かれているようすを思いうかべてたしかめる。\n\n【よくあるまちがい】工場の人のためと思ってしまう。ならべ方は、お客さんのため。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["工場の人", "農家の人", "お客さん"]},
  {"id": "grade_e3_shakai_039", "subject": "shakai", "question": "いろいろな小さな店が、道ぞいにならんでいるところを、何といいますか。", "answer": "商店がい", "hint": "八百屋（やおや）、魚屋、パン屋などが、ならんでいるところだよ。", "explanation": "【何を聞かれているか】小さな店がならぶ道の名前。\n\n【なぜこの答えか】道ぞいに、いろいろな店がならんでいると、お客（きゃく）さんは歩いて、ほしい品物（しなもの）を買いに行ける。このような道を、商店（しょうてん）がいと言うから。\n\n【ステップ1】小さな店が道ぞいにならぶ\n【ステップ2】いろいろな店が1か所（しょ）に集（あつ）まる\n【ステップ3】この場所が商店がい\n\n【答え】商店がい\n\n【たしかめ】自分の町の駅（えき）の近くや、にぎやかな道に、商店がいがあるか思い出してたしかめる。\n\n【よくあるまちがい】スーパーと答えてしまう。スーパーは1つの大きな店。商店がいは小さな店がならぶ道。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["商店がい", "工場", "公園"]},
  {"id": "grade_e3_shakai_040", "subject": "shakai", "question": "りんごが1こ90円です。3こ買うと何円ですか（たとえばの話です）。数字だけで答えましょう。", "answer": "270", "hint": "90円を3回たすのと、同じ計算だよ。", "explanation": "【何を聞かれているか】りんご3この代金（だいきん）。\n\n【なぜこの答えか】1こ90円のりんごを3こ買うので、90円を3回たせばよいから。かけ算にすると、90×3になる。\n\n【ステップ1】1こ90円\n【ステップ2】3こ買うので、90×3\n【ステップ3】90×3＝270\n\n【答え】270\n\n【たしかめ】90＋90＋90をたしても、270になることをたしかめる。\n\n【よくあるまちがい】1この代金90円のまま答えてしまう。3こ分をたすことをわすれない。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_041", "subject": "shakai", "question": "500円玉を出して、330円の品物（しなもの）を買いました。おつりは何円ですか（たとえばの話です）。数字だけで答えましょう。", "answer": "170", "hint": "出したお金から、品物（しなもの）のねだんをひこう。", "explanation": "【何を聞かれているか】買い物（もの）のおつり。\n\n【なぜこの答えか】おつりは、出したお金から品物（しなもの）のねだんをひいたのこりだから。500円から330円をひけばよい。\n\n【ステップ1】出したお金は500円\n【ステップ2】品物は330円\n【ステップ3】500−330＝170\n\n【答え】170\n\n【たしかめ】品物のねだんとおつりをたして、330＋170＝500になることをたしかめる。\n\n【よくあるまちがい】500円と330円をたしてしまう。おつりは、ひき算でもとめる。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_042", "subject": "shakai", "question": "家にいながらネットで注文（ちゅうもん）して、家まで品物（しなもの）をとどけてもらうしくみを、ひらがな4字で何といいますか。", "answer": "たくはい", "hint": "品物（しなもの）を、家まで運（はこ）んでくれるよ。", "explanation": "【何を聞かれているか】家まで品物（しなもの）をとどけるしくみ。\n\n【なぜこの答えか】家にいても買い物ができるように、品物を家までとどけるしくみがある。これを「たくはい」と言うから。\n\n【ステップ1】ネットで注文（ちゅうもん）する\n【ステップ2】品物が家までとどく\n【ステップ3】このしくみをたくはいと言う\n\n【答え】たくはい\n\n【たしかめ】家にたくはいの荷物（にもつ）がとどく場面（ばめん）を思いうかべてたしかめる。\n\n【よくあるまちがい】出荷と思ってしまう。出荷は、工場から品物を送（おく）り出すこと。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["たくはい", "ざいりょう", "けんさ"]},
  {"id": "grade_e3_shakai_043", "subject": "shakai", "question": "レジで品物（しなもの）のねだんを読みとるために、品物についている、しまもようのしるしを、カタカナ5字で何といいますか。", "answer": "バーコード", "hint": "レジできかいにあてると「ピッ」と音が鳴るよ。", "explanation": "【何を聞かれているか】品物（しなもの）についているしまもようのしるし。\n\n【なぜこの答えか】品物には、バーコードがついていて、レジのきかいが読みとると、品物の名前とねだんがわかるから。買い物の時間が早く、まちがいも少なくなる。\n\n【ステップ1】レジできかいにあてる\n【ステップ2】「ピッ」と読みとる\n【ステップ3】しまもようのしるしがバーコード\n\n【答え】バーコード\n\n【たしかめ】家にあるおかしの箱（はこ）や、本などにバーコードがついていることをたしかめる。\n\n【よくあるまちがい】ねふだと思ってしまう。ねふだは、ねだんを書いた紙。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_044", "subject": "shakai", "question": "火事（かじ）が起（お）きたとき、しょうぼうしょにつながる電話の番号（ばんごう）は何ばんですか。数字3けたで答えましょう。", "answer": "119", "hint": "「ひゃくじゅうきゅう」と読むよ。きゅうきゅうのときにも使（つか）う番号（ばんごう）だよ。", "explanation": "【何を聞かれているか】火事（かじ）のときにかける電話の番号（ばんごう）。\n\n【なぜこの答えか】火事のときは、すぐにしょうぼうしょに知らせないと、火が広がってしまう。だから、だれでもおぼえやすい119ばんが決（き）められているから。\n\n【ステップ1】火事を見つけたら、すぐに電話する\n【ステップ2】しょうぼうしょにつながる番号を思い出す\n【ステップ3】119ばん\n\n【答え】119\n\n【たしかめ】電話のボタンを、1・1・9とおして、119になることをたしかめる。\n\n【よくあるまちがい】110ばんと答えてしまう。110はけいさつ、119はしょうぼうしょ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_045", "subject": "shakai", "question": "火事（かじ）のとき、火を消（け）すために水をかける車はどれですか。", "answer": "しょうぼう車", "hint": "赤い色で、サイレンを鳴らして走る車だよ。", "explanation": "【何を聞かれているか】火を消（け）すために水をかける車の名前。\n\n【なぜこの答えか】しょうぼう車は、水やホースなどをつんでいて、火事（かじ）の場所（ばしょ）へかけつけて火を消す車だから。\n\n【ステップ1】火事の場所に行く車を考える\n【ステップ2】水をかけて火を消す車を思いうかべる\n【ステップ3】しょうぼう車\n\n【答え】しょうぼう車\n\n【たしかめ】赤い色の車で、水のホースをのばしているようすを思いうかべてたしかめる。\n\n【よくあるまちがい】きゅうきゅう車と答えてしまう。きゅうきゅう車は、けが人や病人（びょうにん）を運（はこ）ぶ車。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["しょうぼう車", "きゅうきゅう車", "パトカー"]},
  {"id": "grade_e3_shakai_046", "subject": "shakai", "question": "道ばたにあって、火事（かじ）のときに、しょうぼう車が水をとれるようにしてあるしせつはどれですか。", "answer": "しょうかせん", "hint": "地面（じめん）や、かべにつながっている、水が出るところだよ。", "explanation": "【何を聞かれているか】火事（かじ）のときに水をとるしせつの名前。\n\n【なぜこの答えか】火事を消（け）すには、たくさんの水がいる。町のあちこちにしょうかせんがあれば、しょうぼう車がホースをつないで、すぐに水を使（つか）えるから。\n\n【ステップ1】火事を消すには水がいる\n【ステップ2】道ばたに水をとる場所（ばしょ）がある\n【ステップ3】そのしせつがしょうかせん\n\n【答え】しょうかせん\n\n【たしかめ】町を歩いたとき、道ばたに「消火せん」の文字がある場所をさがしてたしかめる。\n\n【よくあるまちがい】ポストと見まちがえる。ポストは手紙を入れるもの。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["ポスト", "しょうかせん", "しん号"]},
  {"id": "grade_e3_shakai_047", "subject": "shakai", "question": "学校やビルにおいてある、火事（かじ）のときに、火を消（け）すための赤い入れ物（もの）のどうぐを、ひらがな5字で何といいますか。", "answer": "しょうかき", "hint": "持（も）ち運（はこ）べる小さなどうぐで、火に向（む）けて使（つか）うよ。", "explanation": "【何を聞かれているか】火を消（け）す赤い入れ物（もの）のどうぐ。\n\n【なぜこの答えか】火事（かじ）は、小さな火のうちなら、自分で消すこともできる。そのために、すぐ使（つか）えるところにしょうかきがおいてあるから。\n\n【ステップ1】火事のさいしょは、小さな火\n【ステップ2】赤い入れ物で、火を消すどうぐを考える\n【ステップ3】そのどうぐがしょうかき\n\n【答え】しょうかき\n\n【たしかめ】学校のろうかの近くに、赤い入れ物がおいてあるか、思い出してたしかめる。\n\n【よくあるまちがい】しょうぼう車と答えてしまう。しょうぼう車は、大きな車。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_048", "subject": "shakai", "question": "火事（かじ）のときににげる出口を、わかりやすくしめす、緑（みどり）色の明かりのしるしのことを、ひらがな6字で何といいますか。", "answer": "ひじょうぐち", "hint": "大きなたてものの出口に、緑（みどり）の人の形のしるしがついているよ。", "explanation": "【何を聞かれているか】にげる出口をしめすしるしの名前。\n\n【なぜこの答えか】火事（かじ）のときは、けむりで前が見えにくくなる。そこで、緑（みどり）色の明かりでひと目でわかるしるしがつけてあり、これをひじょうぐちと言うから。\n\n【ステップ1】火事では、すぐににげたい\n【ステップ2】出口がわからないと、あぶない\n【ステップ3】緑色のしるしをひじょうぐちと言う\n\n【答え】ひじょうぐち\n\n【たしかめ】学校や、お店の出口の上に、緑のしるしがあるか、思い出してたしかめる。\n\n【よくあるまちがい】出入り口と思ってしまう。ひじょうぐちは、火事などの、きんきゅうのときの出口。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_049", "subject": "shakai", "question": "火事（かじ）などのときの、にげ方のきまり「お・か・し・も」の「も」は何ですか。ひらがなで答えましょう。", "answer": "もどらない", "hint": "にげたあとの行動（こうどう）に、気をつけることだよ。", "explanation": "【何を聞かれているか】「お・か・し・も」の「も」。\n\n【なぜこの答えか】「お・か・し・も」は、にげるときにまもる4つのきまり。おさない・かけない・しゃべらない・もどらない。いちど外に出たら、わすれものをとりにもどると、あぶないから。\n\n【ステップ1】お＝おさない\n【ステップ2】か＝かけない、し＝しゃべらない\n【ステップ3】も＝もどらない\n\n【答え】もどらない\n\n【たしかめ】「おさない・かけない・しゃべらない・もどらない」と、4つ声に出して言ってみる。\n\n【よくあるまちがい】「もたない」などと答えてしまう。「も」は「もどらない」。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_050", "subject": "shakai", "question": "火事（かじ）のとき、けむりをすわないように、体をどうしてにげるのがよいですか。ひらがな3字で答えましょう。（「体を〇〇して」の〇〇に入る言葉（ことば））", "answer": "ひくく", "hint": "けむりは、あたたかいので、上のほうにたまりやすいよ。", "explanation": "【何を聞かれているか】火事（かじ）のときの、体の高さ。\n\n【なぜこの答えか】けむりは、あたたかいので上にたまる。ひくい所（ところ）にはけむりが少ないので、体をひくくして、口と鼻（はな）をおさえながらにげると、けむりをすいにくいから。\n\n【ステップ1】けむりは上にたまる\n【ステップ2】ひくい所のほうが、けむりが少ない\n【ステップ3】体をひくくしてにげる\n\n【答え】ひくく\n\n【たしかめ】けむりが天じょうのほうにたまっているようすを思いうかべてたしかめる。\n\n【よくあるまちがい】体を高くしてにげてしまう。けむりは上にたまる。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_051", "subject": "shakai", "question": "119ばんに電話したとき、さいしょにつたえることはどれですか。", "answer": "火事か、きゅうきゅうか", "hint": "電話に出る人が、まず聞くことだよ。", "explanation": "【何を聞かれているか】119ばんでさいしょにつたえること。\n\n【なぜこの答えか】119ばんは、火事（かじ）のときも、きゅうきゅうのときもかける番号（ばんごう）だから。まず、どちらかをつたえると、すぐにちがう係（かかり）の人に取（と）りつぐことができる。\n\n【ステップ1】119ばんは、火事ときゅうきゅうの番号\n【ステップ2】どちらかをさいしょにつたえる\n【ステップ3】火事か、きゅうきゅうかを言う\n\n【答え】火事か、きゅうきゅうか\n\n【たしかめ】電話のあとで、場所（ばしょ）や名前もつたえる、という流（なが）れもたしかめる。\n\n【よくあるまちがい】すきな食べ物（もの）など、ぜんぜんかんけいのないことを言ってしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["火事か、きゅうきゅうか", "天気", "ねだん"]},
  {"id": "grade_e3_shakai_052", "subject": "shakai", "question": "事（じ）こやじけんが起（お）きたとき、けいさつにつながる電話の番号（ばんごう）は何ばんですか。数字3けたで答えましょう。", "answer": "110", "hint": "「ひゃくとおばん」と読むよ。", "explanation": "【何を聞かれているか】事（じ）こやじけんのときにかける電話の番号（ばんごう）。\n\n【なぜこの答えか】事こやじけんのときは、すぐにけいさつに知らせて、助（たす）けをよぶことが大切だから。だれでもおぼえやすい110ばんが決（き）められているから。\n\n【ステップ1】事こやじけんが起（お）きたら、けいさつに知らせる\n【ステップ2】けいさつにつながる番号を思い出す\n【ステップ3】110ばん\n\n【答え】110\n\n【たしかめ】電話のボタンを、1・1・0とおして、110になることをたしかめる。\n\n【よくあるまちがい】119ばんと答えてしまう。119はしょうぼうしょ、110はけいさつ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_053", "subject": "shakai", "question": "道でこまったときに、近くで助（たす）けてくれる、町の小さなけいさつのしせつはどれですか。", "answer": "交番", "hint": "町の角などに、小さなたてものがあって、おまわりさんがいるよ。", "explanation": "【何を聞かれているか】町の小さなけいさつのしせつ。\n\n【なぜこの答えか】交番は、町のあちこちにあって、道あんないや、おとしもののとどけ出など、こまったことの相談（そうだん）に乗（の）ってくれるから。\n\n【ステップ1】町の小さなけいさつを考える\n【ステップ2】図書館（としょかん）や公園は、助（たす）けてくれるしせつではない\n【ステップ3】助けてくれるのは交番\n\n【答え】交番\n\n【たしかめ】学校の近くに、交番があるか、思い出してたしかめる。\n\n【よくあるまちがい】図書館や公園と答えてしまう。こまったときの助けは、交番。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["図書館", "公園", "交番"]},
  {"id": "grade_e3_shakai_054", "subject": "shakai", "question": "けいさつの人が乗（の）る、白と黒の車を、カタカナ4字で何といいますか。", "answer": "パトカー", "hint": "赤い光をまわして、サイレンを鳴らすよ。", "explanation": "【何を聞かれているか】けいさつの人が乗（の）る車の名前。\n\n【なぜこの答えか】パトカーは、町をまわって見まわりをしたり、事（じ）こやじけんの場所（ばしょ）へすぐにかけつけたりする、けいさつの車だから。\n\n【ステップ1】けいさつの人が乗る車を考える\n【ステップ2】白と黒の車を思いうかべる\n【ステップ3】パトカーと言う\n\n【答え】パトカー\n\n【たしかめ】町でパトカーを見かけたとき、白と黒の色になっているか思い出してたしかめる。\n\n【よくあるまちがい】しょうぼう車と答えてしまう。しょうぼう車は赤い車。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_055", "subject": "shakai", "question": "しん号（ごう）で、車や人に「止まれ」をしめす色は何色ですか。漢字（かんじ）1字で答えましょう。", "answer": "赤", "hint": "とても目立つ色で、止まるときの合図に使（つか）われるよ。", "explanation": "【何を聞かれているか】しん号（ごう）の「止まれ」の色。\n\n【なぜこの答えか】赤は、とても目立つ色で、はなれていてもすぐわかるので、「止まれ」をしめす色に決（き）められているから。\n\n【ステップ1】しん号の色は3つ\n【ステップ2】赤・黄・青\n【ステップ3】「止まれ」は赤\n\n【答え】赤\n\n【たしかめ】横（よこ）だんほどうの前で、赤のときに止まることを思い出してたしかめる。\n\n【よくあるまちがい】黄色と答えてしまう。黄色は「止まるじゅんび」、赤は「止まれ」。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_056", "subject": "shakai", "question": "道をわたるところにかかれている、白い、しましまもようを何といいますか。", "answer": "横だんほどう", "hint": "人が道をわたるために、車が止まる場所（ばしょ）だよ。", "explanation": "【何を聞かれているか】道をわたるところの白いもよう。\n\n【なぜこの答えか】横（よこ）だんほどうは、人が安全（あんぜん）に道をわたれるように、車に「人がわたる場所（ばしょ）だ」としらせる、白いしまもようだから。\n\n【ステップ1】道をわたる場所を考える\n【ステップ2】白いしまもようがある\n【ステップ3】この場所を横だんほどうと言う\n\n【答え】横だんほどう\n\n【たしかめ】学校の通学路（つうがくろ）で、白いしまもようをわたる場面（ばめん）を思いうかべてたしかめる。\n\n【よくあるまちがい】ガードレールと見まちがえる。ガードレールは、道のはしにある鉄（てつ）のさく。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["ガードレール", "歩道", "横だんほどう"]},
  {"id": "grade_e3_shakai_057", "subject": "shakai", "question": "通学路（つうがくろ）であぶない目にあったとき、にげこんで助（たす）けをもとめられるのはどこですか。", "answer": "こども110ばんのいえ", "hint": "町の家やお店に、はりがみがしてあるよ。", "explanation": "【何を聞かれているか】あぶないときの、にげこみ先。\n\n【なぜこの答えか】こども110ばんのいえは、子どもがこまったときに、にげこんで助（たす）けをもとめられる家やお店だから。町の人が力を合わせて、子どもを守（まも）っている。\n\n【ステップ1】子どもがあぶない目にあったとき\n【ステップ2】にげこめる家やお店がある\n【ステップ3】それがこども110ばんのいえ\n\n【答え】こども110ばんのいえ\n\n【たしかめ】通学路（つうがくろ）で、110ばんのいえのめじるしがあるか、さがしてたしかめる。\n\n【よくあるまちがい】知らない家に、かってに入ってしまう。めじるしのある家をえらぶ。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["こども110ばんのいえ", "ゲームセンター", "工場"]},
  {"id": "grade_e3_shakai_058", "subject": "shakai", "question": "事（じ）こやじけんのとき、まわりに急（いそ）いでいることを知らせるために鳴らす音を、カタカナ4字で何といいますか。", "answer": "サイレン", "hint": "「ウーウー」と大きく鳴るよ。", "explanation": "【何を聞かれているか】急（いそ）いでいることを知らせる音の名前。\n\n【なぜこの答えか】サイレンは、大きな音で、まわりの車や人に、急いでいることを知らせて、道をあけてもらうためのものだから。\n\n【ステップ1】急いでいるときは、まわりに知らせたい\n【ステップ2】大きな音を出す\n【ステップ3】その音をサイレンと言う\n\n【答え】サイレン\n\n【たしかめ】しょうぼう車やきゅうきゅう車も、サイレンを鳴らすことを思い出してたしかめる。\n\n【よくあるまちがい】ベルと答えてしまう。ベルは、自転車（じてんしゃ）などの小さな音。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_059", "subject": "shakai", "question": "110ばんにかけると、お金がかからない。はいかいいえで答えましょう。", "answer": "はい", "hint": "きんきゅうのときに、お金のしんぱいをしないようにしてあるよ。", "explanation": "【何を聞かれているか】110ばんのお金のこと。\n\n【なぜこの答えか】事（じ）こやじけんのとき、お金のしんぱいで電話をためらうと、助（たす）けがおくれてしまうから。きんきゅうの電話は、お金がかからないようにしてある。\n\n【ステップ1】きんきゅうのときは、すぐに電話したい\n【ステップ2】お金の心配（しんぱい）で電話をためらわないようにする\n【ステップ3】110ばんは、お金がかからない\n\n【答え】はい\n\n【たしかめ】110ばん・119ばんは、どちらも、お金がかからないことをたしかめる。\n\n【よくあるまちがい】お金がかかるから、かけないほうがよいと思ってしまう。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_060", "subject": "shakai", "question": "手紙やはがきを集（あつ）めて、とどける仕事（しごと）をするところはどれですか。", "answer": "ゆうびん局", "hint": "手紙を出すときに使（つか）う、ポストに入れた手紙が集（あつ）められるところだよ。", "explanation": "【何を聞かれているか】手紙をとどける仕事（しごと）をするところ。\n\n【なぜこの答えか】ゆうびん局（きょく）は、ポストなどに入れられた手紙やはがきを集（あつ）めて、分けて、家までとどける仕事をするから。\n\n【ステップ1】手紙はポストに入れる\n【ステップ2】集められた手紙を分けて、とどける\n【ステップ3】この仕事はゆうびん局\n\n【答え】ゆうびん局\n\n【たしかめ】手紙が、出した人から、とどく人までに、ゆうびん局を通ることをたしかめる。\n\n【よくあるまちがい】市役所（しやくしょ）と答えてしまう。市役所は、手つづきをするところ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["ゆうびん局", "市役所", "病院"]},
  {"id": "grade_e3_shakai_061", "subject": "shakai", "question": "図書館（としょかん）の本は、だれのものですか。", "answer": "みんなのもの", "hint": "図書館（としょかん）は、こうきょうのたてものだよ。", "explanation": "【何を聞かれているか】図書館（としょかん）の本の持（も）ち主（ぬし）。\n\n【なぜこの答えか】図書館の本は、みんなが使（つか）えるように、集（あつ）められたものだから。1人でひとりじめせず、ていねいに使って、かえす日までにかえす。\n\n【ステップ1】図書館はこうきょうのたてもの\n【ステップ2】こうきょうのものは、みんなのもの\n【ステップ3】図書館の本はみんなのもの\n\n【答え】みんなのもの\n\n【たしかめ】図書館のきまりで、かえす日がきめられているのは、みんなで使うためとたしかめる。\n\n【よくあるまちがい】自分のものと思って、よごしたり、やぶったりしてしまう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["かりた人だけのもの", "みんなのもの", "先生だけのもの"]},
  {"id": "grade_e3_shakai_062", "subject": "shakai", "question": "病院（びょういん）で、びょう人をしんさつして、病気をなおす仕事（しごと）をする人を、漢字（かんじ）2字で何といいますか。", "answer": "医者", "hint": "「医（い）」の字が入っているよ。", "explanation": "【何を聞かれているか】病院（びょういん）で病気をなおす人。\n\n【なぜこの答えか】病院には、病気やけがをした人が来る。その人の体をしんさつして、くすりを出したり、なおしたりするしごととして行う人が、医者（いしゃ）だから。\n\n【ステップ1】病院には、病気の人が来る\n【ステップ2】体をしんさつして、なおす人を考える\n【ステップ3】その人を医者と言う\n\n【答え】医者\n\n【たしかめ】病院で、白い服（ふく）を着（き）た人が、体をしんさつしているようすを思いうかべてたしかめる。\n\n【よくあるまちがい】かんごしと答えてしまう。かんごしは、医者を助（たす）けて、世話（せわ）をする人。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_063", "subject": "shakai", "question": "病院（びょういん）で、医者（いしゃ）を助（たす）けて、びょう人の世話（せわ）をする人を、ひらがな4字で何といいますか。", "answer": "かんごし", "hint": "ねつをはかったり、くすりを出したりすることもあるよ。", "explanation": "【何を聞かれているか】病院（びょういん）で、びょう人の世話（せわ）をする人。\n\n【なぜこの答えか】病院では、医者（いしゃ）のしんさつのほかに、びょう人の世話をする人もひつようだから。その人を「かんごし」と言い、医者を助（たす）けながら、びょう人の体や心のようすを見まもる。\n\n【ステップ1】病院には、医者のほかにも人がいる\n【ステップ2】びょう人の世話をする人がいる\n【ステップ3】その人をかんごしと言う\n\n【答え】かんごし\n\n【たしかめ】医者としんさつ、かんごしと世話を、わけて考えてたしかめる。\n\n【よくあるまちがい】医者と答えてしまう。医者は、しんさつしてなおす人。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_064", "subject": "shakai", "question": "図書館（としょかん）や公園など、みんなで使（つか）うしせつを使うとき、まもることはどれですか。", "answer": "じゅんばんをまもる", "hint": "みんなで気持（きも）ちよく使（つか）うために、大切なことだよ。", "explanation": "【何を聞かれているか】みんなで使（つか）うしせつの、まもること。\n\n【なぜこの答えか】みんなで使うしせつは、1人のものではない。じゅんばんをまもれば、みんなが気持（きも）ちよく使えるから。\n\n【ステップ1】みんなで使うしせつである\n【ステップ2】ひとりじめしない、こわさない\n【ステップ3】じゅんばんをまもる\n\n【答え】じゅんばんをまもる\n\n【たしかめ】学校の図書室で、本をかりるときも、じゅんばんをまもっていることをたしかめる。\n\n【よくあるまちがい】ひとりじめしてしまう。みんなで使うときは、じゅんばんをまもる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["ひとりじめする", "じゅんばんをまもる", "こわしてもよい"]},
  {"id": "grade_e3_shakai_065", "subject": "shakai", "question": "地図記号（ごう）「◎」は、何をあらわしていますか。", "answer": "市役所", "hint": "市の仕事（しごと）をする、大きなたてものだよ。", "explanation": "【何を聞かれているか】地図記号（ごう）「◎」の意味（いみ）。\n\n【なぜこの答えか】「◎」は、市役所（しやくしょ）をあらわす地図記号で、二重丸（にじゅうまる）の形でかかれるから。地図記号は、どの地図でも同じ意味で使（つか）われるので、はんれいで意味をたしかめて読む。\n\n【ステップ1】地図のはんれいで「◎」をさがす\n【ステップ2】◎は二重丸の形\n【ステップ3】二重丸は市役所の記号\n\n【答え】市役所\n\n【たしかめ】地図のはんれいで、「◎」のとなりに市役所と書いてあるかをたしかめる。\n\n【よくあるまちがい】学校や病院（びょういん）と見まちがえる。◎は市役所。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["学校", "病院", "市役所"]},
  {"id": "grade_e3_shakai_066", "subject": "shakai", "question": "手紙を出すとき、お金のかわりにはる、小さな紙を、ひらがな3字で何といいますか。", "answer": "きって", "hint": "手紙のおもてに、はるよ。", "explanation": "【何を聞かれているか】手紙にはる、小さな紙。\n\n【なぜこの答えか】手紙をとどけてもらうには、お金がかかる。そのお金をはらったしるしとして、はる小さな紙が「きって」だから。\n\n【ステップ1】手紙をとどけるには、お金がいる\n【ステップ2】お金をはらったしるしをはる\n【ステップ3】その紙をきってと言う\n\n【答え】きって\n\n【たしかめ】手紙にきってをはって、ポストに入れる流（なが）れをたしかめる。\n\n【よくあるまちがい】シールと答えてしまう。シールはきってではない。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_067", "subject": "shakai", "question": "駅（えき）で、電車を待（ま）つとき、立って待つ場所（ばしょ）を、カタカナ3字で何といいますか。", "answer": "ホーム", "hint": "電車が止まる、はしの高い場所（ばしょ）だよ。", "explanation": "【何を聞かれているか】電車を待（ま）つ場所（ばしょ）の名前。\n\n【なぜこの答えか】駅（えき）には、電車に乗（の）りおりするために、人が立つ場所がある。そこをホームと言い、電車とのあいだに、すき間があるので、気をつけて待つひつようがあるから。\n\n【ステップ1】電車に乗りおりする場所を考える\n【ステップ2】線路（せんろ）のそばの、平（たい）らな場所\n【ステップ3】その場所がホーム\n\n【答え】ホーム\n\n【たしかめ】駅で、ホームのはしの白い線の内がわで待つ、というきまりをたしかめる。\n\n【よくあるまちがい】線路の中に入ってしまう。ホームでは、白い線の内がわで待つ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_068", "subject": "shakai", "question": "むかし、ごはんをたくときに、まきをもやして使（つか）った、土やレンガでつくったどうぐを、ひらがな3字で何といいますか。", "answer": "かまど", "hint": "上にかまをのせて、下で火をもやしたよ。", "explanation": "【何を聞かれているか】むかしの、ごはんをたくどうぐ。\n\n【なぜこの答えか】むかしは、電気やガスがなかったので、ごはんをたくときには、まきをもやして火をおこした。その火を使（つか）うためにつくられたどうぐが、かまどだから。\n\n【ステップ1】むかしは、まきをもやして火を使った\n【ステップ2】土やレンガでかこいをつくる\n【ステップ3】このどうぐをかまどと言う\n\n【答え】かまど\n\n【たしかめ】社会科の本で、かまどの絵を見て、上にかまがのっているかたしかめる。\n\n【よくあるまちがい】ストーブと答えてしまう。ストーブは、部屋（へや）をあたためるどうぐ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_069", "subject": "shakai", "question": "むかし、せんたくをするときに、ごしごしこすってあらうために使（つか）った、木の板（いた）を、何といいますか。ひらがな6字で答えましょう。", "answer": "せんたくいた", "hint": "手でこすって、よごれを落（お）とす板（いた）だよ。", "explanation": "【何を聞かれているか】むかしの、せんたくのどうぐ。\n\n【なぜこの答えか】むかしは、電気せんたくきがなかったので、水の中で、せんたくものを板（いた）にこすりつけて、よごれを落（お）とした。そのときに使（つか）った板が、せんたくいただから。\n\n【ステップ1】むかしは、手でせんたくした\n【ステップ2】板に、せんたくものをこすりつけた\n【ステップ3】その板をせんたくいたと言う\n\n【答え】せんたくいた\n\n【たしかめ】社会科の本で、せんたくいたの絵を見て、ぎざぎざした板になっているかたしかめる。\n\n【よくあるまちがい】せんたくきと答えてしまう。せんたくきは、電気で動（うご）く。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_070", "subject": "shakai", "question": "むかし、水をくむために、地面（じめん）に深（ふか）くほったあなを、ひらがな2字で何といいますか。", "answer": "いど", "hint": "水道がなかったころ、家の近くにあったよ。", "explanation": "【何を聞かれているか】むかしの、水をくむ場所（ばしょ）。\n\n【なぜこの答えか】むかしは、水道がなかったので、地面（じめん）に深（ふか）いあなをほって、地下の水をくんだ。そのあなを「いど」と言う。水をくむには、つるべというどうぐを使（つか）った。\n\n【ステップ1】むかしは、水道がなかった\n【ステップ2】地面に深いあなをほる\n【ステップ3】そのあなをいどと言う\n\n【答え】いど\n\n【たしかめ】社会科の本で、いどの絵を見て、水をくむようすをたしかめる。\n\n【よくあるまちがい】川と答えてしまう。川は、しぜんにできた水の流（なが）れ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_071", "subject": "shakai", "question": "むかし、夜の明かりに使（つか）われた、油（あぶら）をもやして火をともす、ガラスのかさのついたどうぐを、カタカナ3字で何といいますか。", "answer": "ランプ", "hint": "電気がなかったころ、夜の部屋（へや）を明るくしたよ。", "explanation": "【何を聞かれているか】むかしの、夜の明かりのどうぐ。\n\n【なぜこの答えか】むかしは、電気がなかったので、夜は油（あぶら）をもやして明かりをとった。そのときに使（つか）った、ガラスのかさのついた明かりが、ランプだから。\n\n【ステップ1】むかしは、電気がなかった\n【ステップ2】油をもやして火をともす\n【ステップ3】その明かりをランプと言う\n\n【答え】ランプ\n\n【たしかめ】社会科の本で、ランプの絵を見て、ガラスのかさがついているかたしかめる。\n\n【よくあるまちがい】ちょうちんと答えてしまう。ちょうちんは、紙でつくった明かり。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_072", "subject": "shakai", "question": "せんたくいたの次（つぎ）に使（つか）われるようになった、電気で動（うご）くせんたくのどうぐはどれですか。", "answer": "電気せんたくき", "hint": "板（いた）でこするかわりに、水をぐるぐる回してあらうよ。", "explanation": "【何を聞かれているか】電気で動（うご）く、せんたくのどうぐ。\n\n【なぜこの答えか】電気が家に通るようになると、手であらう手間をへらすために、電気で水をまわしてあらう、電気せんたくきがつくられたから。\n\n【ステップ1】むかしは、せんたくいたであらった\n【ステップ2】電気で動く、せんたくのどうぐをさがす\n【ステップ3】電気せんたくきが使（つか）われるようになった\n\n【答え】電気せんたくき\n\n【たしかめ】今の家にある、せんたくきを見て、電気で動くことをたしかめる。\n\n【よくあるまちがい】電気すいはんきと答えてしまう。すいはんきは、ごはんをたくどうぐ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["電気せんたくき", "電気すいはんき", "ランプ"]},
  {"id": "grade_e3_shakai_073", "subject": "shakai", "question": "かまどでごはんをたくかわりに、電気を使（つか）ってごはんをたく、どうぐはどれですか。", "answer": "電気すいはんき", "hint": "スイッチをおすと、ごはんがたけるよ。", "explanation": "【何を聞かれているか】電気で動（うご）く、ごはんをたくどうぐ。\n\n【なぜこの答えか】電気が使（つか）えるようになると、まきをもやして火かげんを見るかわりに、スイッチひとつでごはんをたける、電気すいはんきがつくられたから。\n\n【ステップ1】むかしは、かまどでごはんをたいた\n【ステップ2】電気を使うごはんのどうぐをさがす\n【ステップ3】電気すいはんきが使われるようになった\n\n【答え】電気すいはんき\n\n【たしかめ】今の家で、ごはんをたくどうぐが電気で動いていることをたしかめる。\n\n【よくあるまちがい】電気せんたくきと答えてしまう。せんたくきは、あらうどうぐ。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["せんたくいた", "電気すいはんき", "ランプ"]},
  {"id": "grade_e3_shakai_074", "subject": "shakai", "question": "夜の明かりは、ランプからやがて何にかわりましたか。漢字（かんじ）2字で答えましょう。", "answer": "電気", "hint": "スイッチをおすと、明るくなるよ。", "explanation": "【何を聞かれているか】ランプのあとの、夜の明かり。\n\n【なぜこの答えか】電気が家に通るようになると、スイッチひとつで明るくなる電気の明かりが使（つか）われるようになったから。ランプのように、油（あぶら）をたすひつようもない。\n\n【ステップ1】むかしは、ランプを使った\n【ステップ2】スイッチで明るくなる明かりをさがす\n【ステップ3】電気の明かりが使われるようになった\n\n【答え】電気\n\n【たしかめ】今の家で、夜の明かりが電気になっていることをたしかめる。\n\n【よくあるまちがい】ろうそくと答えてしまう。ろうそくも昔（むかし）の明かりだが、ランプの次（つぎ）は電気。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_075", "subject": "shakai", "question": "むかしの、くらしを調（しら）べるとき、お年よりに話を聞く調べ方を何といいますか。", "answer": "聞きとり", "hint": "話を聞いて、メモをとる調（しら）べ方だよ。", "explanation": "【何を聞かれているか】話を聞いて調（しら）べるほうほうの名前。\n\n【なぜこの答えか】むかしのことは、そのときにくらしていた人が一番よく知っている。話を聞いて、メモをとりながら調べるほうほうを、聞きとりと言うから。\n\n【ステップ1】むかしのことを知りたい\n【ステップ2】お年よりは、むかしのくらしを知っている\n【ステップ3】話を聞いて調べるほうほうが聞きとり\n\n【答え】聞きとり\n\n【たしかめ】聞きとりのあとに、メモをまとめて、わかったことを書きとめる。\n\n【よくあるまちがい】見学と答えてしまう。見学は、見に行って調べるほうほう。", "difficulty": "standard", "examType": "chugaku", "grade": "e3", "choices": ["聞きとり", "見学", "発表"]},
  {"id": "grade_e3_shakai_076", "subject": "shakai", "question": "むかし、かまどでごはんをたくときに、もやしたものはなんですか。ひらがな2字で答えましょう。", "answer": "まき", "hint": "山や森から切ってきた、木をわったものだよ。", "explanation": "【何を聞かれているか】かまどで、もやしたもの。\n\n【なぜこの答えか】かまどは、火をもやしてごはんをたくどうぐ。そのときに、山や森から切ってきた木をわったものを、「まき」としてもやしたから。\n\n【ステップ1】かまどでは火をもやす\n【ステップ2】もやすものは、木をわったもの\n【ステップ3】その木をまきと言う\n\n【答え】まき\n\n【たしかめ】社会科の本で、かまどの絵を見て、まきがもえているかたしかめる。\n\n【よくあるまちがい】石炭（せきたん）と答えてしまう。かまどでは、まきをもやすことが多い。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_077", "subject": "shakai", "question": "できごとを、年のじゅんにならべて書いた表（ひょう）を、漢字（かんじ）2字で何といいますか。", "answer": "年表", "hint": "年を、たてや横（よこ）にならべて書くよ。", "explanation": "【何を聞かれているか】できごとを年のじゅんにならべた表（ひょう）の名前。\n\n【なぜこの答えか】できごとを年のじゅんにならべると、いつ、何が起（お）きたかがひと目でわかり、かわってきたようすも見つけやすくなるから。この表を年表と言う。\n\n【ステップ1】できごとを、年のじゅんにならべる\n【ステップ2】ひと目でかわってきたことがわかる\n【ステップ3】この表を年表と言う\n\n【答え】年表\n\n【たしかめ】年表を見て、古いできごとから新しいできごとへ、じゅんに読めるかたしかめる。\n\n【よくあるまちがい】地図と答えてしまう。地図は場所（ばしょ）をあらわすもの。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_078", "subject": "shakai", "question": "人口のふえ方などを、ぼうの高さであらわすグラフはどれですか。", "answer": "ぼうグラフ", "hint": "数が多いほど、ぼうが高くなるよ。", "explanation": "【何を聞かれているか】ぼうの高さで数をあらわすグラフ。\n\n【なぜこの答えか】ぼうグラフは、数をぼうの高さであらわすので、数が多いか少ないかを、ひと目でくらべられるから。人口のふえ方を見るのにも向（む）いている。\n\n【ステップ1】ぼうの高さで数をあらわす\n【ステップ2】ぼうが高いほど、数が多い\n【ステップ3】このグラフをぼうグラフと言う\n\n【答え】ぼうグラフ\n\n【たしかめ】ぼうグラフを見て、いちばん高いぼうが、いちばん数が多いことをたしかめる。\n\n【よくあるまちがい】年表（ねんぴょう）と答えてしまう。年表は、できごとをならべた表。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["ぼうグラフ", "地図", "年表"]},
  {"id": "grade_e3_shakai_079", "subject": "shakai", "question": "ある市の人口は、10年前は4万人、今は6万人です（たとえばの話です）。何万人ふえましたか。数字だけで答えましょう。", "answer": "2", "hint": "今の数から、10年前の数をひこう。", "explanation": "【何を聞かれているか】人口がふえた数。\n\n【なぜこの答えか】ふえた数は、今の数から前の数をひいてもとめるから。6万人から4万人をひけばよい。\n\n【ステップ1】10年前は4万人\n【ステップ2】今は6万人\n【ステップ3】6−4＝2（万人）\n\n【答え】2\n\n【たしかめ】10年前の4万人にふえた数をたして、4＋2＝6になることをたしかめる。\n\n【よくあるまちがい】10年前と今をたして10と答えてしまう。ふえた数は、ひき算でもとめる。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_080", "subject": "shakai", "question": "むかしの写真（しゃしん）と今の写真をならべて見ると、何がわかりますか。", "answer": "かわったところ", "hint": "写真（しゃしん）にうつっている場所（ばしょ）が、同じかどうかに注目（ちゅうもく）しよう。", "explanation": "【何を聞かれているか】むかしの写真（しゃしん）と今の写真をならべて見てわかること。\n\n【なぜこの答えか】同じ場所（ばしょ）のむかしの写真と今の写真をくらべると、ようすがどのようにかわったか、また、かわらないところはどこかがわかるから。\n\n【ステップ1】同じ場所の写真を2まいならべる\n【ステップ2】ちがいを見つける\n【ステップ3】かわったところがわかる\n\n【答え】かわったところ\n\n【たしかめ】写真の中の、たてものや道が、同じか、ちがうかを1つずつくらべてたしかめる。\n\n【よくあるまちがい】写真を見ても、何もわからないと思ってしまう。くらべると、ちがいがわかる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["作った人の名前", "ねだん", "かわったところ"]},
  {"id": "grade_e3_shakai_081", "subject": "shakai", "question": "むかしの市の地図には田が6まいありましたが、今は2まいしかのこっていません（たとえばの話です）。田は何まいへりましたか。数字だけで答えましょう。", "answer": "4", "hint": "むかしの数から、今の数をひこう。", "explanation": "【何を聞かれているか】へった田の数。\n\n【なぜこの答えか】へった数は、むかしの数から今の数をひいてもとめるから。6まいから2まいをひけばよい。\n\n【ステップ1】むかしは6まい\n【ステップ2】今は2まい\n【ステップ3】6−2＝4（まい）\n\n【答え】4\n\n【たしかめ】今の2まいに、へった4まいをたすと、2＋4＝6になることをたしかめる。\n\n【よくあるまちがい】6と2をたして8と答えてしまう。へった数は、ひき算でもとめる。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_082", "subject": "shakai", "question": "古い写真（しゃしん）と今の写真を2まいならべて、同じところとちがうところを見つけるとき、2まいを何しますか。ひらがな4字で答えましょう。", "answer": "くらべる", "hint": "2つをならべて、同じところとちがうところを見つけることだよ。", "explanation": "【何を聞かれているか】2まいの写真（しゃしん）を見て、ちがいを見つけること。\n\n【なぜこの答えか】2まいの写真を見て、ちがいを見つけるには、ならべて見くらべることがひつようだから。くらべると、かわったところや、かわらないところがわかる。\n\n【ステップ1】2まいの写真をならべる\n【ステップ2】同じところとちがうところをさがす\n【ステップ3】これを「くらべる」と言う\n\n【答え】くらべる\n\n【たしかめ】写真の中のたてものや道を、1つずつ見くらべて、ちがいをたしかめる。\n\n【よくあるまちがい】「見る」だけで終（お）えてしまう。くらべることで、ちがいが見えてくる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_083", "subject": "shakai", "question": "ぼうグラフで、人口が2万人、3万人、5万人の3つのぼうがありました（たとえばの話です）。いちばん多い人口は何万人ですか。数字だけで答えましょう。", "answer": "5", "hint": "いちばん高いぼうの数を読もう。", "explanation": "【何を聞かれているか】ぼうグラフでいちばん多い人口。\n\n【なぜこの答えか】ぼうグラフは、高いぼうほど、数が多いことをあらわすから。2万人、3万人、5万人の中で、いちばん大きい数は5万人。\n\n【ステップ1】ぼうは3つ\n【ステップ2】数は2・3・5\n【ステップ3】いちばん大きい数は5\n\n【答え】5\n\n【たしかめ】3つのぼうの高さをくらべて、いちばん高いぼうが、5万人かたしかめる。\n\n【よくあるまちがい】ぼうの数をたして10と答えてしまう。聞かれているのは、いちばん多いぼう。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_084", "subject": "shakai", "question": "人口がだんだんふえているとき、ぼうグラフのぼうは、じゅんにどうなりますか。", "answer": "高くなる", "hint": "人口がふえると、ぼうも大きくなるよ。", "explanation": "【何を聞かれているか】人口がふえるときの、ぼうグラフのぼうのようす。\n\n【なぜこの答えか】ぼうグラフでは、数が大きいほどぼうが高くなる。人口がふえつづけると、ぼうもだんだん高くなっていくから。\n\n【ステップ1】ぼうの高さは、数の大きさ\n【ステップ2】人口がふえると、数も大きくなる\n【ステップ3】ぼうはだんだん高くなる\n\n【答え】高くなる\n\n【たしかめ】ぼうグラフの左から右へ、ぼうの高さを見て、高くなっているかたしかめる。\n\n【よくあるまちがい】ひくくなると答えてしまう。人口がふえるとぼうは高くなる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["高くなる", "ひくくなる", "かわらない"]},
  {"id": "grade_e3_shakai_085", "subject": "shakai", "question": "毎年、同じころに行われる行事（ぎょうじ）を、漢字（かんじ）4字で何といいますか。", "answer": "年中行事", "hint": "1年じゅう、きまった時期（じき）にくりかえされる行事（ぎょうじ）のことだよ。", "explanation": "【何を聞かれているか】毎年同じころに行われる行事（ぎょうじ）の名前。\n\n【なぜこの答えか】正月、ひなまつり、七夕など、毎年同じころに行われる行事は、ひとまとめにして年中行事と言うから。むかしからつづいてきた行事が多い。\n\n【ステップ1】毎年同じころに行う行事を考える\n【ステップ2】正月や七夕などがある\n【ステップ3】これらをまとめて年中行事と言う\n\n【答え】年中行事\n\n【たしかめ】カレンダーで、毎年同じ月に行われる行事を思い出してたしかめる。\n\n【よくあるまちがい】まつりだけを年中行事と思ってしまう。正月や七夕も年中行事。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_086", "subject": "shakai", "question": "3月3日に、女の子のせいちょうをいわって、ひな人形をかざる行事（ぎょうじ）を、ひらがな5字で何といいますか。", "answer": "ひなまつり", "hint": "3月3日に、ひな人形をかざるよ。", "explanation": "【何を聞かれているか】3月3日の行事（ぎょうじ）の名前。\n\n【なぜこの答えか】3月3日に、女の子がすこやかに育（そだ）つことをねがって、ひな人形をかざる行事があり、「ひなまつり」と言うから。\n\n【ステップ1】3月3日の行事を考える\n【ステップ2】ひな人形をかざる行事\n【ステップ3】この行事をひなまつりと言う\n\n【答え】ひなまつり\n\n【たしかめ】「3月3日」と「ひな人形」の2つがそろっているかをたしかめる。\n\n【よくあるまちがい】七夕と答えてしまう。七夕は7月7日。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_087", "subject": "shakai", "question": "5月5日に、こいのぼりをかざる行事（ぎょうじ）はどれですか。", "answer": "こどもの日", "hint": "5月5日の行事（ぎょうじ）で、こいのぼりが空をおよぐよ。", "explanation": "【何を聞かれているか】5月5日の行事（ぎょうじ）の名前。\n\n【なぜこの答えか】5月5日は、子どもが元気に育（そだ）つことをねがう日で、こいのぼりをかざる。この日を「こどもの日」と言うから。\n\n【ステップ1】5月5日の行事を考える\n【ステップ2】こいのぼりをかざる日\n【ステップ3】この日をこどもの日と言う\n\n【答え】こどもの日\n\n【たしかめ】「5月5日」と「こいのぼり」の組み合わせをたしかめる。\n\n【よくあるまちがい】ひなまつりと答えてしまう。ひなまつりは3月3日。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["こどもの日", "ひなまつり", "七夕"]},
  {"id": "grade_e3_shakai_088", "subject": "shakai", "question": "7月7日の夜、たんざくにねがいごとを書いて、ささにかざる行事（ぎょうじ）を、漢字（かんじ）2字で何といいますか。", "answer": "七夕", "hint": "星にねがいをかける行事（ぎょうじ）だよ。", "explanation": "【何を聞かれているか】7月7日の行事（ぎょうじ）の名前。\n\n【なぜこの答えか】7月7日の夜、たんざくにねがいごとを書いて、ささにかざる行事があるから。この行事を七夕と書いて、たなばたと読む。\n\n【ステップ1】7月7日の行事を考える\n【ステップ2】たんざくにねがいごとを書く\n【ステップ3】この行事を七夕と書く\n\n【答え】七夕\n\n【たしかめ】「七」と「夕」の2つの字で、7月7日の夕方の行事と思い出してたしかめる。\n\n【よくあるまちがい】こどもの日と答えてしまう。こどもの日は5月5日。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_089", "subject": "shakai", "question": "神社（じんじゃ）の入口に立っている、門のようなものはどれですか。", "answer": "とりい", "hint": "赤い色で、柱（はしら）が2本立っているよ。", "explanation": "【何を聞かれているか】神社（じんじゃ）の入口にある門のようなもの。\n\n【なぜこの答えか】神社の入口には、神さまのいる場所（ばしょ）のはじまりをしめす、とりいが立っているから。ここからが神さまの場所と考えられている。\n\n【ステップ1】神社の入口を考える\n【ステップ2】赤い柱（はしら）が2本立つ門\n【ステップ3】この門をとりいと言う\n\n【答え】とりい\n\n【たしかめ】神社に行ったときに、入口に赤い門があることを思い出してたしかめる。\n\n【よくあるまちがい】かまどやランプと答えてしまう。それらは、むかしの道具（どうぐ）。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["かまど", "ランプ", "とりい"]},
  {"id": "grade_e3_shakai_090", "subject": "shakai", "question": "地いきの古いたてものや、おどりなどを、これからの人にのこすために守（まも）っていくものは、何とよばれますか。", "answer": "文化ざい", "hint": "大切に守（まも）って、これから先につたえていくものだよ。", "explanation": "【何を聞かれているか】大切に守（まも）りつたえていく古いたてものなどの名前。\n\n【なぜこの答えか】地いきの古いたてものやおどりは、むかしからつたわる大切なたからだから。守ってこれから先につたえるものを、文化（ぶんか）ざいと言う。\n\n【ステップ1】古いたてものや、おどりを思いうかべる\n【ステップ2】大切に守って、これからの人にのこす\n【ステップ3】これらを文化ざいと言う\n\n【答え】文化ざい\n\n【たしかめ】地いきのお寺や神社（じんじゃ）にある古いたてものを、文化ざいかどうかたしかめる。\n\n【よくあるまちがい】工場や店と答えてしまう。文化ざいは、むかしからつたわる大切なもの。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["文化ざい", "工場", "店"]},
  {"id": "grade_e3_shakai_091", "subject": "shakai", "question": "夏のまつりで、地いきの人がみんなでわになって、おどるおどりを、ひらがな5字で何といいますか。", "answer": "ぼんおどり", "hint": "夏の夜に、やぐらのまわりでおどるよ。", "explanation": "【何を聞かれているか】夏のまつりのおどりの名前。\n\n【なぜこの答えか】夏のまつりでは、地いきの人たちがみんなでわになっておどる、ぼんおどりが行われることが多いから。むかしから受（う）けつがれてきた。\n\n【ステップ1】夏のまつりを思いうかべる\n【ステップ2】やぐらのまわりでみんなでおどる\n【ステップ3】そのおどりをぼんおどりと言う\n\n【答え】ぼんおどり\n\n【たしかめ】夏のまつりに行ったとき、わになっておどる人たちを見たことを思い出してたしかめる。\n\n【よくあるまちがい】ダンスと答えてしまう。ダンスは、外国から来たおどり。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_092", "subject": "shakai", "question": "むかしから、地いきの人たちが、歌やおどりなどを、受（う）けついできたものを、ひらがな4字で「でんとう〇〇〇〇」と言います。〇〇〇〇に入る言葉（ことば）は何ですか。", "answer": "げいのう", "hint": "歌や、おどり、おはやしなどのことだよ。", "explanation": "【何を聞かれているか】「でんとう〇〇〇〇」に入る言葉（ことば）。\n\n【なぜこの答えか】歌や、おどり、おはやしなどのわざは、むかしから地いきの人たちが受（う）けついできた。このようなものを、でんとうげいのうと言うから。\n\n【ステップ1】歌やおどりを受けつぐ\n【ステップ2】むかしからつたわるわざ\n【ステップ3】でんとうげいのうと言う\n\n【答え】げいのう\n\n【たしかめ】地いきのまつりで見たおどりや、おはやしが、でんとうげいのうかをたしかめる。\n\n【よくあるまちがい】「でんとうせいひん」と答えてしまう。ここでは歌やおどりのことを聞いている。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_093", "subject": "shakai", "question": "見学に行ったとき、見たことや聞いたことを書いて、のこしておくものを、カタカナ2字で何といいますか。", "answer": "メモ", "hint": "手がきで、短（みじか）く書きとめておくものだよ。", "explanation": "【何を聞かれているか】見たことや聞いたことを書きとめるもの。\n\n【なぜこの答えか】見学では、たくさんのことを見たり聞いたりする。あとでわすれないように、短（みじか）く書いておくものがメモだから。\n\n【ステップ1】見学では、たくさんのことがわかる\n【ステップ2】わすれないように書きとめる\n【ステップ3】書きとめたものをメモと言う\n\n【答え】メモ\n\n【たしかめ】見学のあとで、メモを見て、わかったことが思い出せるかたしかめる。\n\n【よくあるまちがい】何も書かずに、頭だけでおぼえようとしてしまう。メモをとる。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_094", "subject": "shakai", "question": "だれかに話を聞いて調（しら）べることを、カタカナ6字で何といいますか。", "answer": "インタビュー", "hint": "テレビで、人にしつ問（もん）をしている場面（ばめん）を思い出そう。", "explanation": "【何を聞かれているか】話を聞いて調（しら）べるほうほうの名前。\n\n【なぜこの答えか】人に話を聞くと、本だけではわからない、くわしいことが知れるから。この調べ方を、インタビューと言う。\n\n【ステップ1】調べたいことの、くわしい人を考える\n【ステップ2】話を聞いて、メモをとる\n【ステップ3】これをインタビューと言う\n\n【答え】インタビュー\n\n【たしかめ】インタビューする前に、聞きたいことを、紙に書き出しておく、というじゅんびもたしかめる。\n\n【よくあるまちがい】見学と答えてしまう。見学は、行って見て調べるほうほう。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_095", "subject": "shakai", "question": "ひょうに、りんごが5こ、みかんが8こ、バナナが3こと書いてあります（たとえばの話です）。みかんは、りんごより何こ多いですか。数字だけで答えましょう。", "answer": "3", "hint": "8から5をひいて、ちがいをもとめよう。", "explanation": "【何を聞かれているか】みかんとりんごの数のちがい。\n\n【なぜこの答えか】ちがいをもとめるには、大きいほうの数から小さいほうの数をひくから。みかんの8こから、りんごの5こをひけばよい。\n\n【ステップ1】みかんは8こ\n【ステップ2】りんごは5こ\n【ステップ3】8−5＝3\n\n【答え】3\n\n【たしかめ】りんごの5こに、ちがいの3こをたすと、5＋3＝8になることをたしかめる。\n\n【よくあるまちがい】みかんとバナナをくらべてしまう。聞かれているのは、りんごとのちがい。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_096", "subject": "shakai", "question": "学校の図書室の本を、ぼうグラフにしました。絵本が12さつ、図かんが7さつ、物語（ものがたり）が9さつです（たとえばの話です）。いちばん少ない本は何さつですか。数字だけで答えましょう。", "answer": "7", "hint": "3つの数をくらべて、いちばん小さい数をさがそう。", "explanation": "【何を聞かれているか】いちばん少ない本の数。\n\n【なぜこの答えか】いちばん少ないものは、数がいちばん小さいもの。12、7、9をくらべると、いちばん小さい数は7だから。\n\n【ステップ1】絵本は12さつ\n【ステップ2】図かんは7さつ、物語（ものがたり）は9さつ\n【ステップ3】いちばん小さい数は7\n\n【答え】7\n\n【たしかめ】3つのぼうの高さをくらべて、いちばんひくいぼうが7さつかたしかめる。\n\n【よくあるまちがい】いちばん多い12と答えてしまう。聞かれているのは、いちばん少ないもの。", "difficulty": "standard", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_097", "subject": "shakai", "question": "調（しら）べたことを、1まいの大きな紙にまとめて、見出しや記事（きじ）を書いたものを、漢字（かんじ）2字で何といいますか。", "answer": "新聞", "hint": "毎日、家にとどくものと同じ名前だよ。", "explanation": "【何を聞かれているか】調（しら）べたことをまとめて書く、大きな紙の名前。\n\n【なぜこの答えか】調べたことを、見出しと記事（きじ）に分けて、1まいの紙にまとめたものを、新聞と言う。人につたえるのに、わかりやすいから。\n\n【ステップ1】調べたことを、まとめて書く\n【ステップ2】見出しと記事に分ける\n【ステップ3】このまとめ方を新聞と言う\n\n【答え】新聞\n\n【たしかめ】新聞に、見出し、記事、写真（しゃしん）や絵がそろっているかたしかめる。\n\n【よくあるまちがい】ポスターと答えてしまう。ここでは、見出しと記事がある、新聞のこと。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
  {"id": "grade_e3_shakai_098", "subject": "shakai", "question": "新聞で、記事（きじ）のないようがひと目でわかるように、大きく書く部分（ぶぶん）はどれですか。", "answer": "見出し", "hint": "新聞の記事（きじ）のいちばん上に、大きな字で書いてあるよ。", "explanation": "【何を聞かれているか】新聞で、記事（きじ）のないようをひと目でしらせる部分（ぶぶん）。\n\n【なぜこの答えか】見出しは、記事のないようを、短（みじか）い言葉（ことば）でひと目でわかるように、大きな字で書いたもの。読む人は、見出しを見て、読みたい記事をえらべるから。\n\n【ステップ1】新聞には、記事がたくさんある\n【ステップ2】記事の上に、大きな字で書く\n【ステップ3】その部分が見出し\n\n【答え】見出し\n\n【たしかめ】新聞の記事を1つ見て、いちばん上に大きな字の見出しがあるかたしかめる。\n\n【よくあるまちがい】記事と答えてしまう。記事は、くわしい文章（ぶんしょう）の部分。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["記事", "写真", "見出し"]},
  {"id": "grade_e3_shakai_099", "subject": "shakai", "question": "自分の目で見て、場所（ばしょ）や仕事（しごと）のようすを調（しら）べることを何といいますか。", "answer": "見学", "hint": "工場や店に、実（じっ）さいに行って、見せてもらうことだよ。", "explanation": "【何を聞かれているか】見に行って調（しら）べるほうほうの名前。\n\n【なぜこの答えか】見学は、実（じっ）さいにその場所（ばしょ）に行って、自分の目で見て調べるほうほうだから。本では分からないことも、見学をすると分かる。\n\n【ステップ1】調べたい場所に行く\n【ステップ2】自分の目で見る\n【ステップ3】この調べ方を見学と言う\n\n【答え】見学\n\n【たしかめ】見学のあとで、見たことをメモにまとめて、見学のないようをたしかめる。\n\n【よくあるまちがい】発表（はっぴょう）と答えてしまう。発表は、調べたことをつたえること。", "difficulty": "basic", "examType": "chugaku", "grade": "e3", "choices": ["見学", "発表", "宿題"]},
  {"id": "grade_e3_shakai_100", "subject": "shakai", "question": "調（しら）べる→まとめる→（　）というじゅんで、調べたことをみんなの前で話してつたえるさいごの学習（がくしゅう）を、ひらがな5字で何といいますか。", "answer": "はっぴょう", "hint": "聞いてくれる人に向（む）かって、大きな声で話すよ。", "explanation": "【何を聞かれているか】調（しら）べたことをみんなにつたえること。\n\n【なぜこの答えか】調べて、まとめただけでは、まだほかの人にはつたわらない。まとめたことを、みんなの前で話してつたえることを、はっぴょうと言うから。\n\n【ステップ1】まず、調べる\n【ステップ2】次（つぎ）に、まとめる\n【ステップ3】さいごに、はっぴょうする\n\n【答え】はっぴょう\n\n【たしかめ】調べる→まとめる→はっぴょうの3つがじゅんにならんでいるかたしかめる。\n\n【よくあるまちがい】調べる前にはっぴょうしてしまう。はっぴょうは、さいご。", "difficulty": "basic", "examType": "chugaku", "grade": "e3"},
];
